pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 deposit, uint256 am) public {
        deposit = bound(deposit, 1 ether, 1000 ether);
        vm.warp(block.timestamp + 1);

        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), deposit);
        attacker.deposit(deposit);

        am = bound(am, 1, deposit);
        attacker.withdraw(am);

        // Invariant: after Collect(am), balance == deposit - am,
        // no matter what the callee's receive() attempts (reentrancy blocked).
        assertTrue(c.Acc(address(attacker)) == deposit - am);
    }
}

