pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 dep, uint256 amt) public {
        uint256 d = bound(dep, 1 ether, 20 ether);
        uint256 a = bound(amt, 1 ether, d);
        vm.assume(d < 20 * a);

        Attacker atk = new Attacker(c);
        vm.deal(address(atk), 1 ether);

        // attacker deposits d (unlockTime set to now)
        vm.prank(address(atk));
        c.Put{value: d}(0);

        uint256 before = address(atk).balance;
        for (uint256 i = 0; i < 20; i++) {
            vm.warp(block.timestamp + 1);
            try atk.hit(a) {
                // keep collecting
            } catch {
                break;
            }
        }

        // General rule: total ether extracted must never exceed the amount deposited.
        assertTrue(address(atk).balance - before <= d);
    }
}

contract Attacker {
    C immutable c;
    uint256 am;

    constructor(C _c) {
        c = _c;
    }

    function hit(uint256 a) external {
        am = a;
        c.Collect(a);
    }

    receive() external payable {
        // re-enter Put during Collect's external call (only possible in the mutant)
        c.Put{value: am}(0);
    }
}

