pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 deposit, uint256 unlockDelta, uint256 am) public {
        vm.assume(deposit >= 1 ether && deposit <= 1000 ether);
        am = bound(am, 1, deposit);
        unlockDelta = bound(unlockDelta, 1, 365 days);

        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), deposit);
        vm.prank(address(attacker));
        attacker.deposit(block.timestamp + unlockDelta);

        uint256 before = deposit;
        vm.warp(block.timestamp + unlockDelta + 1);

        vm.prank(address(attacker));
        attacker.withdraw(am);

        (, uint256 balAfter) = c.Acc(address(attacker));
        // Rule: the reentrant Put attempt inside the attacker's callback fails in the
        // guarded reference, so the Collect is cancelled and the recorded balance is
        // unchanged; the mutant's unguarded Put succeeds and the balance drops by am.
        assertTrue(balAfter == before);
    }
}

contract Attacker {
    C target;
    constructor(C t) { target = t; }
    function deposit(uint256 unlockTime) external payable {
        target.Put{value: msg.value}(unlockTime);
    }
    function withdraw(uint256 amount) external {
        target.Collect(amount);
    }
    receive() external payable {
        // re-entrant Put: reverts in the guarded reference, succeeds in the mutant
        target.Put(0);
    }
}
}

