pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 deposit, uint256 am, uint256 rv) public {
        deposit = bound(deposit, 1 ether, 1000 ether);
        am = bound(am, 1 ether, deposit);
        rv = bound(rv, 1, 10 ether);
        vm.assume(rv != am || deposit - am + rv != deposit);

        ReentrantAttacker attacker = new ReentrantAttacker(c);
        attacker.setReentryValue(rv);

        vm.deal(address(attacker), deposit);
        attacker.deposit(deposit);

        // fast-forward so unlockTime has passed
        vm.warp(block.timestamp + 1 days);

        attacker.attack(am);

        // Universal rule: when the re-entrant Put inside the callback reverts
        // (reentrancy lock), the withdrawal is cancelled and the recorded
        // balance stays exactly the deposited amount.
        assertTrue(c.Acc(address(attacker)).balance() == deposit);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public reval;

    constructor(C t) { target = t; }

    function setReentryValue(uint256 v) external { reval = v; }

    function deposit(uint256 amount) external payable {
        target.Put{value: amount}(0);
    }

    function attack(uint256 am) external {
        target.Collect(am);
    }

    receive() external payable {
        target.Put{value: reval}(0);
    }
}

