pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C(address(new Log()));
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 deposit, uint256 delay, uint256 am) public {
        deposit = bound(deposit, 1 ether, 1000 ether);
        delay = bound(delay, 1, 365 days);
        am = bound(am, 1 ether, deposit);

        uint256 start = block.timestamp + 1000;
        vm.warp(start);

        // attacker deposits with a future unlock time
        vm.deal(address(attacker), deposit);
        attacker.doPut(start + delay, deposit);

        // time passes past the unlock time
        uint256 collectTime = start + delay + 1;
        vm.warp(collectTime);

        // attacker collects; its receive() re-enters via fallback Put(0)
        attacker.attack(am);

        // Rule: the recorded unlock time is untouched by a Collect whose
        // callback re-enters Put — the guard makes the nested Put revert,
        // cancelling the whole Collect. In the mutant the nested Put(0)
        // succeeds and resets unlockTime to `collectTime`.
        assertTrue(c.Acc(address(attacker)).unlockTime == start + delay);
    }
}

contract Attacker {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function doPut(uint256 unlockTime, uint256 amount) external payable {
        c.Put{value: amount}(unlockTime);
    }

    function attack(uint256 am) external {
        c.Collect(am);
    }

    receive() external payable {
        // re-enter through the fallback (which calls Put(0))
        address(c).call{value: 0}("");
    }
}
