pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint64 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        uint256 deposit = amount;
        vm.deal(actor, deposit);
        uint256 before = c.Acc(actor).balance;
        vm.prank(actor);
        c.Put{value: deposit}(0);
        assertEq(c.Acc(actor).balance, before + deposit, "Put must credit msg.value");
    }
}

