pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant INIT = 2 ether;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 reentrantAmount) public {
        amount = bound(amount, 1, INIT);
        reentrantAmount = bound(reentrantAmount, 0, 10 ether);

        Attacker att = new Attacker(c);
        vm.deal(address(att), INIT + reentrantAmount + 1 ether);

        // deposit so Collect is admissible (balance >= MinSum, unlockTime passed)
        vm.prank(address(att));
        c.Put{value: INIT}(0);
        vm.warp(block.timestamp + 1 days);

        // collect: c pays the attacker, whose receive() re-enters Put with reentrantAmount
        vm.prank(address(att));
        c.Collect(amount);

        // Rule: after a successful Collect of `amount`, the recorded balance
        // must be exactly INIT - amount (no unauthorized re-entrant credit).
        assertTrue(c.Acc(address(att)) == INIT - amount);
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {
        c.Put{value: msg.value}(0);
    }
}
